/**
 ******************************************************************************
 * @file    tom_fx_render.c
 * TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tom's sound output subsystem (best-ui), with an AI coding assistant;
 *          Brendon (integrator) added FX_REQ_RESTORE and the carry in every reply (30 Oct 2026, with an AI coding assistant).
 * @brief   FxRenderTask: turns chunks of a recording into chunks of its
 *          effect file.
 *
 * What it does: effects are made ahead of time, one file per effect (for
 * example FX/ECHO/REC05.WAV), so no effect has to run while sound plays.
 * JackStorageTask reads the recording off the card and sends it here one
 * chunk (up to 512 samples) at a time; this task runs the effect on it with
 * FxRender (PD5b_Tom/Application/FxRender: the 2:3 upsampler, then
 * AudioEffects_ProcessBlock: the old live chain's steps) and sends the
 * 48 kHz result back; Jack writes it to the card. This task never touches
 * the card or any peripheral: it only computes.
 *
 * RTOS role: FxRenderTask, created by App_RTOS_Init() with static memory
 * (FX_RENDER_STACK_BYTES of stack). It blocks on fxRenderReqQueue
 * (osWaitForever) and answers on fxRenderReplyQueue with timeout 0: at most
 * one request is ever out and the queue holds two, so the answer always
 * fits (a refused put would be counted in g_rtos_dropped.fx_render, which
 * the debug screen's System page shows). The chunk buffer is the
 * one block of fxChunkPool, and whoever holds its pointer owns it (slide
 * 31): from the request until this task's reply it is this task's.
 *
 * Why the lowest priority (osPriorityIdle, FreeRTOS 1, just above the
 * kernel's own idle task): making a file is the only long computation in
 * the toy (Autotune: about 10 s of CPU for a 10 s recording). At the bottom
 * it only gets CPU time that no other task wants, so the screen, the
 * buttons and the sound are never slowed down by it, and the files are
 * made while the toy is idle. Jack decides which file is made first.
 *
 * Its state, s_render (about 23 KB: the only AudioEffectsState in the
 * firmware), is a static in .bss: all zeros at boot and never initialised
 * here, because FxRender_Begin sets everything up at the start of a file.
 *
 * One chunk (never more than one out at a time):
 *
 *   JackStorageTask (Normal)                          FxRenderTask (Idle, the lowest)
 *   1. take the fxChunkPool block, fill in[]
 *   2. put FxRenderReq_t ---- fxRenderReqQueue ---->  3. wake up, check the request;
 *      (meanwhile: commands, 2-tick waits)               first chunk: FxRender_Begin;
 *                                                        the effect: in[] -> out[]
 *   5. get the reply <---- fxRenderReplyQueue ------  4. put FxRenderReply_t
 *      copy out[], free the block
 *
 * Main steps of the loop:
 *   1. wait for a request
 *   2. check it (request_is_valid); a bad one is answered BAD_REQUEST
 *   3. first chunk of a file (FX_REQ_FIRST): FxRender_Begin(effect, rate)
 *   3a. a file made again carries on here (FX_REQ_RESTORE): load the carry
 *      Jack sent in chunk->carry (a carry that is none or another effect's
 *      is answered BAD_REQUEST)
 *   4. FxRender_Process: in[] -> out[]
 *   5. save the carry into chunk->carry (Jack keeps it, in case the file is
 *      stopped here and made again from the middle later)
 *   6. reply with the same chunk pointer and job number
 ******************************************************************************/
#include "app_rtos.h"
#include "fx_render.h"
#include <stdbool.h>
#include <string.h>

/* request_is_valid() checks Jack's chunks against AUDIO_BLOCK_SAMPLES, but
 * FxRender cuts them by FX_RENDER_BLOCK_SAMPLES: the check keeps the old
 * live chain's block grid only while the two are the same number. */
_Static_assert(AUDIO_BLOCK_SAMPLES == FX_RENDER_BLOCK_SAMPLES,
               "request_is_valid's block size is FxRender's block grid");
/* The carry travels in FxChunk_t.carry (app_rtos.h) and is Tom's FxRender
 * carry byte for byte. */
_Static_assert(FX_CARRY_BYTES == FX_RENDER_CARRY_BYTES, "FxChunk_t.carry holds one FxRender carry");

/* UiEffect_t (the effect numbers the UI and Jack use, app_rtos.h) ->
 * AudioEffectMode (Tom's DSP). UI_EFFECT_NONE has no effect file. */
static const AudioEffectMode s_mode_of[UI_EFFECT_COUNT] = {
    [UI_EFFECT_NONE] = AUDIO_EFFECT_AUTOTUNE,   /* never used: NONE is refused */
    [UI_EFFECT_1]    = AUDIO_EFFECT_AUTOTUNE,
    [UI_EFFECT_2]    = AUDIO_EFFECT_PITCH_UP,
    [UI_EFFECT_3]    = AUDIO_EFFECT_PITCH_DOWN,
    [UI_EFFECT_4]    = AUDIO_EFFECT_ROBOT,
    [UI_EFFECT_5]    = AUDIO_EFFECT_ECHO,
    [UI_EFFECT_6]    = AUDIO_EFFECT_REVERB,
};

/* The file being made: its effect's history and the upsampler (~23.3 KB, .bss). */
static FxRender s_render;

/* A chunk can be worked on: a buffer, 1..512 samples, and whole 64-sample
 * blocks unless it is the file's last chunk (FxRender keeps the old live
 * chain's block grid only if every chunk but the last is whole blocks). */
static bool request_is_valid(const FxRenderReq_t *req)
{
    if (req->chunk == NULL) {
        return false;
    }
    if (req->n_in == 0U || req->n_in > FX_RENDER_CHUNK_IN) {
        return false;
    }
    if ((req->flags & FX_REQ_LAST) != 0U) {
        return true;
    }
    return (req->n_in % AUDIO_BLOCK_SAMPLES) == 0U;
}

/* The first chunk of a file: clear the effect's history and set it up for
 * this effect and source rate. False for an unknown effect. */
static bool begin_file(const FxRenderReq_t *req)
{
    if (req->effect < (uint8_t)UI_EFFECT_1 || req->effect >= (uint8_t)UI_EFFECT_COUNT) {
        return false;
    }
    const uint32_t rate_hz = req->src_48k ? FX_RENDER_RATE_48K_HZ : FX_RENDER_RATE_32K_HZ;
    return FxRender_Begin(&s_render, s_mode_of[req->effect], rate_hz) == AUDIO_EFFECTS_STATUS_OK;
}

/* A request this task cannot work on: no samples, and Jack stops the job. */
static FxRenderReply_t bad_request(FxRenderReply_t reply)
{
    reply.n_out  = 0U;
    reply.status = FX_STATUS_BAD_REQUEST;
    return reply;
}

/* Work on one request and build its reply. */
static FxRenderReply_t render_chunk(const FxRenderReq_t *req)
{
    FxRenderReply_t reply;
    memset(&reply, 0, sizeof(reply));
    reply.chunk = req->chunk;           /* the buffer goes back to its owner, Jack */
    reply.job   = req->job;             /* lets Jack drop a late reply of a job he has aborted */

    if (!request_is_valid(req)) {
        return bad_request(reply);
    }
    if ((req->flags & FX_REQ_FIRST) != 0U && !begin_file(req)) {
        return bad_request(reply);
    }
    /* TEAM CODE (written by Brendon, 30 Oct 2026): a file made again from
     * the middle carries on here. The pre-roll before this chunk refilled
     * the effect's delay lines; the carry puts back what never forgets. A
     * carry that is none or another effect's is refused: no wrong file. */
    if ((req->flags & FX_REQ_RESTORE) != 0U &&
        FxRender_LoadCarry(&s_render, req->chunk->carry) != AUDIO_EFFECTS_STATUS_OK) {
        return bad_request(reply);
    }

    uint32_t n_out = 0U;
    const AudioEffectsStatus status = FxRender_Process(&s_render, req->chunk->in, req->n_in,
                                                       req->chunk->out, FX_RENDER_CHUNK_OUT, &n_out);
    /* An effect error is not fatal: that part went through dry, as the live
     * chain did, n_out is still right, and the status (1..0x7F) only tells
     * Jack. Only an error with no output at all (a bad length) stops the job. */
    if (status != AUDIO_EFFECTS_STATUS_OK && n_out == 0U) {
        return bad_request(reply);
    }
    /* Every reply carries the carry after this chunk (a 44-byte copy, next
     * to nothing beside the effect): Jack keeps the latest, so wherever a
     * file is stopped, he has the carry of that very point. */
    FxRender_SaveCarry(&s_render, req->chunk->carry);
    reply.n_out  = (uint16_t)n_out;
    reply.status = (uint8_t)status;
    return reply;
}

void TomFx_TaskEntry(void *argument)
{
    (void)argument;

    for (;;) {
        FxRenderReq_t request;
        if (osMessageQueueGet(fxRenderReqQueue, &request, NULL, osWaitForever) != osOK) {
            continue;
        }
        FxRenderReply_t reply = render_chunk(&request);
        (void)App_RTOS_Put(fxRenderReplyQueue, &reply, 0U, &g_rtos_dropped.fx_render);
    }
}
